const batchStatusKeys: Record<string, TranslationKey> = {
  ACTIVE: 'batch.active', PARTIALLY_RETURNED: 'batch.partiallyReturned', RETURNED: 'batch.returned',
  'Издадена партида': 'batch.active', 'Частично върната партида': 'batch.partiallyReturned', 'Върната партида': 'batch.returned',
}

export type StatusDomain = 'machine' | 'repair' | 'part' | 'batch'

export function statusText(
  translator: (key: TranslationKey, values?: Values) => string,
  status: string,
  domain: StatusDomain = 'machine',
): string {
  const maps = { machine: machineStatusKeys, repair: repairStatusKeys, part: partStatusKeys, batch: batchStatusKeys }
  const key = maps[domain][status]
  return key ? translator(key) : status
}

type UserPreference = { preferred_language: Locale }
type I18nContextValue = {
  locale: Locale
  setLocale: (locale: Locale, persistRemotely?: boolean) => void
  t: (key: TranslationKey, values?: Values) => string
  date: (value: string | Date) => string
  number: (value: number) => string
}

const defaultContext: I18nContextValue = {
  locale: DEFAULT_LOCALE,
  setLocale: () => undefined,
  t: (key, values) => translate(DEFAULT_LOCALE, key, values),
  date: (value) => formatDate(DEFAULT_LOCALE, value),
  number: (value) => formatNumber(DEFAULT_LOCALE, value),
}

const I18nContext = createContext<I18nContextValue>(defaultContext)

export function I18nProvider({ children, initialLocale }: { children: ReactNode; initialLocale?: Locale }) {
  const [locale, setLocaleState] = useState<Locale>(initialLocale || getStoredLocale())

  const applyLocale = useCallback((nextLocale: Locale, persistRemotely: boolean) => {
    setLocaleState(nextLocale)
    storeLocale(nextLocale)
    document.documentElement.lang = nextLocale
    if (persistRemotely && storedUser()) {
      void api<UserPreference>('/users/me/preferences', {
        method: 'PATCH',
        body: JSON.stringify({ preferred_language: nextLocale }),
      }).catch(() => undefined)
    }
  }, [])

  useEffect(() => {
    document.documentElement.lang = locale
    const user = storedUser()
    if (user && isLocale(user.preferred_language)) {
      applyLocale(user.preferred_language, false)
    }
  }, [applyLocale])

  const value = useMemo<I18nContextValue>(() => ({
    locale,
    setLocale: (nextLocale, persistRemotely = true) => applyLocale(nextLocale, persistRemotely),
    t: (key, values) => translate(locale, key, values),
    date: (input) => formatDate(locale, input),
    number: (input) => formatNumber(locale, input),
  }), [applyLocale, locale])

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n(): I18nContextValue {
  return useContext(I18nContext)
}
